@Test
public void testStatementSet() throws IOException, InterpreterException {
    if (flinkInterpreter.getFlinkVersion().getMinorVersion() == 12) {
        LOGGER.warn("Skip Flink 1.12 as statement set is not supported before 1.12");
        return;
    }
    hiveShell.execute("create table source_table (id int, name string)");
    hiveShell.execute("insert into source_table values(1, 'name')");
    File destDir = Files.createTempDirectory("flink_test").toFile();
    FileUtils.deleteDirectory(destDir);
    InterpreterContext context = getInterpreterContext();
    InterpreterResult result = sqlInterpreter.interpret("CREATE TABLE dest_table (\n" + "id int,\n" + "name string" + ") WITH (\n" + "'format.field-delimiter'=',',\n" + "'connector.type'='filesystem',\n" + "'format.derive-schema'='true',\n" + "'connector.path'='" + destDir.getAbsolutePath() + "',\n" + "'format.type'='csv'\n" + ");", context);
    assertEquals(context.out.toString(), InterpreterResult.Code.SUCCESS, result.code());
    File destDir2 = Files.createTempDirectory("flink_test").toFile();
    FileUtils.deleteDirectory(destDir2);
    context = getInterpreterContext();
    result = sqlInterpreter.interpret("CREATE TABLE dest_table2 (\n" + "id int,\n" + "name string" + ") WITH (\n" + "'format.field-delimiter'=',',\n" + "'connector.type'='filesystem',\n" + "'format.derive-schema'='true',\n" + "'connector.path'='" + destDir2.getAbsolutePath() + "',\n" + "'format.type'='csv'\n" + ");", context);
    assertEquals(context.out.toString(), InterpreterResult.Code.SUCCESS, result.code());
    // insert into 2 sink tables in one statement set
    context = getInterpreterContext();
    result = sqlInterpreter.interpret("begin statement set;\n" + "insert into dest_table select * from source_table;\n" + "insert into dest_table2 select * from source_table;\n" + "end;", context);
