    final String expectedScript = SHELL_EXTENSION.replace("TABLE_LIMIT_PLACEHOLDER", interpreter.getProperty("mongo.shell.command.table.limit")).replace("TARGET_DB_PLACEHOLDER", interpreter.getProperty("mongo.server.database")).replace("USER_NAME_PLACEHOLDER", interpreter.getProperty("mongo.server.username")).replace("PASSWORD_PLACEHOLDER", interpreter.getProperty("mongo.server.password")).replace("AUTH_DB_PLACEHOLDER", interpreter.getProperty("mongo.server.authenticationDatabase")) + userScript;
    // The script that is executed must contain the functions provided by this interpreter
    assertEquals(expectedScript, resultScript, "Check SCRIPT");
}

