@Test
void testPythonProcessKilled() throws InterruptedException, TimeoutException {
    final Waiter waiter = new Waiter();
    Thread thread = new Thread() {

        @Override
        public void run() {
            try {
                InterpreterResult result = interpreter.interpret("import time\ntime.sleep(1000)", getInterpreterContext());
                waiter.assertEquals(InterpreterResult.Code.ERROR, result.code());
                waiter.assertEquals("Python process is abnormally exited, please check your code and log.", result.message().get(0).getData());
            } catch (InterpreterException e) {
