@Test
void testSparkVersion() {
    // test equals
    assertEquals(SparkVersion.SPARK_3_5_0, SparkVersion.fromVersionString("3.5.0"));
    assertEquals(SparkVersion.SPARK_3_5_0, SparkVersion.fromVersionString("3.5.0-SNAPSHOT"));
    // test vendor spark version
    assertEquals(SparkVersion.SPARK_3_5_0, SparkVersion.fromVersionString("3.5.0.2.5.0.0-1245"));
    // test newer than
    assertTrue(SparkVersion.SPARK_3_5_0.newerThan(SparkVersion.SPARK_3_3_0));
    assertTrue(SparkVersion.SPARK_3_5_0.newerThanEquals(SparkVersion.SPARK_3_5_0));
    assertFalse(SparkVersion.SPARK_3_3_0.newerThan(SparkVersion.SPARK_3_5_0));
    // test older than
    assertTrue(SparkVersion.SPARK_3_3_0.olderThan(SparkVersion.SPARK_3_5_0));
    assertTrue(SparkVersion.SPARK_3_5_0.olderThanEquals(SparkVersion.SPARK_3_5_0));
    assertFalse(SparkVersion.SPARK_3_5_0.olderThan(SparkVersion.SPARK_3_3_0));
    // test newerThanEqualsPatchVersion
    assertTrue(SparkVersion.fromVersionString("2.3.1").newerThanEqualsPatchVersion(SparkVersion.fromVersionString("2.3.0")));
    assertFalse(SparkVersion.fromVersionString("2.3.1").newerThanEqualsPatchVersion(SparkVersion.fromVersionString("2.3.2")));
    assertFalse(SparkVersion.fromVersionString("2.3.1").newerThanEqualsPatchVersion(SparkVersion.fromVersionString("2.2.0")));
    // conversion
    assertEquals(30500, SparkVersion.SPARK_3_5_0.toNumber());
    assertEquals("3.5.0", SparkVersion.SPARK_3_5_0.toString());
}

