@Test
void testRunOnSelectionChange() throws Exception {
    try {
        String xpathToRunOnSelectionChangeCheckbox = getParagraphXPath(1) + "//ul/li/form/input[contains(@ng-checked, 'true')]";
        String xpathToDropdownMenu = getParagraphXPath(1) + "//select";
        String xpathToResultText = getParagraphXPath(1) + "//div[contains(@id,\"_html\")]";
        createNewNote();
        waitForParagraph(1, "READY");
        setTextOfParagraph(1, "%md My selection is ${my selection=1,1|2|3}");
        runParagraph(1);
        waitForParagraph(1, "FINISHED");
        // 1. 'RunOnSelectionChange' is true by default
        manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//span[@class='icon-settings']")).click();
        assertTrue(manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//ul/li/form/input[contains(@ng-click, 'turnOnAutoRun(paragraph)')]")).isDisplayed(), "'Run on selection change' checkbox will be shown under dropdown menu");
        Select dropDownMenu = new Select(manager.getWebDriver().findElement(By.xpath((xpathToDropdownMenu))));
        dropDownMenu.selectByVisibleText("2");
        waitForParagraph(1, "FINISHED");
        assertEquals("My selection is 2", manager.getWebDriver().findElement(By.xpath(xpathToResultText)).getText(), "If 'RunOnSelectionChange' is true, the paragraph result will be updated right after click any options in the dropdown menu ");
        // 2. set 'RunOnSelectionChange' to false
        manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//span[@class='icon-settings']")).click();
        manager.getWebDriver().findElement(By.xpath(xpathToRunOnSelectionChangeCheckbox)).click();
        assertTrue(manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//ul/li/span[contains(@ng-if, 'paragraph.config.runOnSelectionChange == false')]")).isDisplayed(), "If 'Run on selection change' checkbox is unchecked, 'paragraph.config.runOnSelectionChange' will be false ");
        Select sameDropDownMenu = new Select(manager.getWebDriver().findElement(By.xpath((xpathToDropdownMenu))));
        sameDropDownMenu.selectByVisibleText("1");
        waitForParagraph(1, "FINISHED");
        assertEquals("My selection is 2", manager.getWebDriver().findElement(By.xpath(xpathToResultText)).getText(), "If 'RunOnSelectionChange' is false, the paragraph result won't be updated even if we select any options in the dropdown menu ");
        // run paragraph manually by pressing ENTER
        manager.getWebDriver().findElement(By.xpath(xpathToDropdownMenu)).sendKeys(Keys.ENTER);
        waitForParagraph(1, "FINISHED");
        assertEquals("My selection is 1", manager.getWebDriver().findElement(By.xpath(xpathToResultText)).getText(), "Even if 'RunOnSelectionChange' is set as false, still can run the paragraph by pressing ENTER ");
    } catch (Exception e) {
        handleException("Exception in ParagraphActionsIT while testRunOnSelectionChange ", e);
    }
}

