@Test
void testSimpleAction() throws Exception {
    try {
        // step 1 : (admin) create a new note, run a paragraph and turn on personalized mode
        authenticationUser("admin", "password1");
        By locator = By.xpath("//div[contains(@class, \"col-md-4\")]/div/h5/a[contains(.,'Create new" + " note')]");
        WebDriverWait wait = new WebDriverWait(manager.getWebDriver(), Duration.ofSeconds(MAX_BROWSER_TIMEOUT_SEC));
        WebElement element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        if (element.isDisplayed()) {
            createNewNote();
        }
        String noteId = manager.getWebDriver().getCurrentUrl().substring(manager.getWebDriver().getCurrentUrl().lastIndexOf("/") + 1);
        waitForParagraph(1, "READY");
        setParagraphText("Before");
        assertEquals("Before", manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//div[contains(@class, 'markdown-body')]")).getText());
        pollingWait(By.xpath("//*[@id='actionbar']" + "//button[contains(@uib-tooltip, 'Switch to personal mode')]"), MAX_BROWSER_TIMEOUT_SEC).click();
        clickAndWait(By.xpath("//div[@class='modal-dialog'][contains(.,'Do you want to personalize your analysis?')" + "]//div[@class='modal-footer']//button[contains(.,'OK')]"));
        logoutUser("admin");
        // step 2 : (user1) make sure it is on personalized mode and 'Before' in result of paragraph
        authenticationUser("user1", "password2");
        locator = By.xpath("//*[@id='notebook-names']//a[contains(@href, '" + noteId + "')]");
        wait = new WebDriverWait(manager.getWebDriver(), Duration.ofSeconds(MAX_BROWSER_TIMEOUT_SEC));
        element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        if (element.isDisplayed()) {
            pollingWait(By.xpath("//*[@id='notebook-names']//a[contains(@href, '" + noteId + "')]"), MAX_BROWSER_TIMEOUT_SEC).click();
        }
        assertEquals("Switch to personal mode (owner can change)", manager.getWebDriver().findElement(By.xpath("//*[@id='actionbar']" + "//button[contains(@class, 'btn btn-default btn-xs ng-scope ng-hide')]")).getAttribute("uib-tooltip"));
        waitForParagraph(1, "READY");
        runParagraph(1);
        assertEquals("Before", manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//div[contains(@class, 'markdown-body')]")).getText());
        logoutUser("user1");
        // step 3 : (admin) change paragraph contents to 'After' and check result of paragraph
        authenticationUser("admin", "password1");
        locator = By.xpath("//*[@id='notebook-names']//a[contains(@href, '" + noteId + "')]");
        element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        if (element.isDisplayed()) {
            pollingWait(By.xpath("//*[@id='notebook-names']//a[contains(@href, '" + noteId + "')]"), MAX_BROWSER_TIMEOUT_SEC).click();
        }
        waitForParagraph(1, "FINISHED");
        setParagraphText("After");
        assertEquals("After", manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//div[contains(@class, 'markdown-body')]")).getText());
        logoutUser("admin");
        // step 4 : (user1) check whether result is 'Before' or not
        authenticationUser("user1", "password2");
        locator = By.xpath("//*[@id='notebook-names']//a[contains(@href, '" + noteId + "')]");
        element = wait.until(ExpectedConditions.visibilityOfElementLocated(locator));
        if (element.isDisplayed()) {
            pollingWait(By.xpath("//*[@id='notebook-names']//a[contains(@href, '" + noteId + "')]"), MAX_BROWSER_TIMEOUT_SEC).click();
        }
        assertEquals("Before", manager.getWebDriver().findElement(By.xpath(getParagraphXPath(1) + "//div[contains(@class, 'markdown-body')]")).getText());
        logoutUser("user1");
    } catch (Exception e) {
        handleException("Exception in PersonalizeActionsIT while testSimpleAction ", e);
    }
}

