@Test
void testIRInterpreter() throws InterpreterException, IOException {
    InterpreterContext context = getInterpreterContext();
    InterpreterResult result = interpreter.interpret("1+1", context);
    assertEquals(InterpreterResult.Code.SUCCESS, result.code());
    List<InterpreterResultMessage> resultMessages = context.out.toInterpreterResultMessage();
    assertEquals(1, resultMessages.size());
    assertEquals(InterpreterResult.Type.HTML, resultMessages.get(0).getType(), resultMessages.toString());
    assertEquals("2", resultMessages.get(0).getData(), resultMessages.toString());
    // error
    context = getInterpreterContext();
    result = interpreter.interpret("unknown_var", context);
    assertEquals(InterpreterResult.Code.ERROR, result.code());
    resultMessages = context.out.toInterpreterResultMessage();
    assertEquals(1, resultMessages.size());
    assertEquals(InterpreterResult.Type.TEXT, resultMessages.get(0).getType(), result.toString());
    assertTrue(resultMessages.get(0).getData().contains("unknown_var"), resultMessages.toString());
    // depends on JVM language
    // assertTrue(resultMessages.get(0).getData().contains("object 'unknown_var' not found"),
    // resultMessages.toString());
    context = getInterpreterContext();
    result = interpreter.interpret("foo <- TRUE\n" + "print(foo)\n" + "bare <- c(1, 2.5, 4)\n" + "print(bare)\n" + "double <- 15.0\n" + "print(double)", context);
    assertEquals(InterpreterResult.Code.SUCCESS, result.code());
    resultMessages = context.out.toInterpreterResultMessage();
    assertEquals(1, resultMessages.size());
    assertEquals(InterpreterResult.Type.TEXT, resultMessages.get(0).getType(), result.toString());
    assertTrue(resultMessages.get(0).getData().contains("[1] TRUE\n" + "[1] 1.0 2.5 4.0\n" + "[1] 15\n"), resultMessages.toString());
    // plotting
    context = getInterpreterContext();
    result = interpreter.interpret("hist(mtcars$mpg)", context);
    assertEquals(InterpreterResult.Code.SUCCESS, result.code());
    resultMessages = context.out.toInterpreterResultMessage();
    assertEquals(1, resultMessages.size());
    assertEquals(InterpreterResult.Type.IMG, resultMessages.get(0).getType(), resultMessages.toString());
    // ggplot2
    result = interpreter.interpret("library(ggplot2)\n" + "ggplot(diamonds, aes(x=carat, y=price, color=cut)) + geom_point()", getInterpreterContext());
    assertEquals(InterpreterResult.Code.SUCCESS, result.code());
    resultMessages = context.out.toInterpreterResultMessage();
    assertEquals(1, resultMessages.size());
    assertEquals(InterpreterResult.Type.IMG, resultMessages.get(0).getType(), resultMessages.toString());
    // googlevis
    // TODO(zjffdu) It is weird that googlevis doesn't work with spark 2.2
    if (ENABLE_GOOGLEVIS_TEST) {
        context = getInterpreterContext();
        result = interpreter.interpret("library(googleVis)\n" + "df=data.frame(country=c(\"US\", \"GB\", \"BR\"), \n" + "              val1=c(10,13,14), \n" + "              val2=c(23,12,32))\n" + "Bar <- gvisBarChart(df)\n" + "print(Bar, tag = 'chart')", context);
        assertEquals(InterpreterResult.Code.SUCCESS, result.code());
        resultMessages = context.out.toInterpreterResultMessage();
        assertEquals(2, resultMessages.size());
        assertEquals(InterpreterResult.Type.HTML, resultMessages.get(1).getType(), resultMessages.toString());
        assertTrue(resultMessages.get(1).getData().contains("javascript"), resultMessages.get(1).getData());
    }
