@Test
void testInterpreterRestart() throws IOException, InterruptedException {
    String noteId = null;
    try {
        // when: create new note
        noteId = notebook.createNote("note1", anonymous);
        String pId = notebook.processNote(noteId, note -> {
            Paragraph p = note.addNewParagraph(AuthenticationInfo.ANONYMOUS);
            Map<String, Object> config = p.getConfig();
            config.put("enabled", true);
            // when: run markdown paragraph
            p.setConfig(config);
            p.setText("%md markdown");
            p.setAuthenticationInfo(anonymous);
            note.run(p.getId());
            return p.getId();
        });
        Status status = notebook.processNote(noteId, note -> {
            Paragraph p = note.getParagraph(pId);
            return p.getStatus();
        });
        while (status != Status.FINISHED) {
            Thread.sleep(100);
            status = notebook.processNote(noteId, note -> {
                Paragraph p = note.getParagraph(pId);
                return p.getStatus();
            });
        }
        List<InterpreterSetting> settings = notebook.processNote(noteId, note -> {
            Paragraph p = note.getParagraph(pId);
            assertEquals(p.getReturn().message().get(0).getData(), getSimulatedMarkdownResult("markdown"));
            return note.getBindedInterpreterSettings(new ArrayList<>());
        });
        // when: restart interpreter
        for (InterpreterSetting setting : settings) {
            if (setting.getName().equals("md")) {
                // call restart interpreter API
                CloseableHttpResponse put = httpPut("/interpreter/setting/restart/" + setting.getId(), "");
                assertThat("test interpreter restart:", put, isAllowed());
                put.close();
                break;
            }
        }
        // when: run markdown paragraph, again
        String p2Id = notebook.processNote(noteId, note -> {
            Paragraph p = note.addNewParagraph(AuthenticationInfo.ANONYMOUS);
            Map<String, Object> config = p.getConfig();
            config.put("enabled", true);
            // when: run markdown paragraph
            p.setConfig(config);
            p.setText("%md markdown restarted");
            p.setAuthenticationInfo(anonymous);
