        }.getType());
        assertEquals("OK", resp.get("status"));
        delete.close();
        for (Paragraph p : paragraphs) {
            p.waitUntilFinished();
            assertEquals(Job.Status.ABORT, p.getStatus());
        }
    } finally {
        // cleanup
        if (null != note1Id) {
            notebook.removeNote(note1Id, anonymous);
