@Test
void testIsUserAuthorized() {
    List<String> userAndRoles = new ArrayList<>();
    userAndRoles.add("User1");
    userAndRoles.add("Role1");
    userAndRoles.add("Role2");
    List<String> owners;
    InterpreterSetting interpreterSetting;
    InterpreterOption interpreterOption;
    // With match
    owners = new ArrayList<>();
    owners.add("Role1");
    interpreterOption = new InterpreterOption();
    interpreterOption.setUserPermission(true);
    interpreterOption.owners = owners;
    interpreterSetting = new InterpreterSetting.Builder().setId("id").setName("id").setGroup("group").setOption(interpreterOption).setConf(zConf).create();
    assertTrue(interpreterSetting.isUserAuthorized(userAndRoles));
    // Without match
    owners = new ArrayList<>();
    owners.add("Role88");
    interpreterOption = new InterpreterOption();
    interpreterOption.setUserPermission(true);
    interpreterOption.owners = owners;
    interpreterSetting = new InterpreterSetting.Builder().setId("id").setName("id").setGroup("group").setOption(interpreterOption).setConf(zConf).create();
    assertFalse(interpreterSetting.isUserAuthorized(userAndRoles));
    // Without permissions
    owners = new ArrayList<>();
    interpreterOption = new InterpreterOption();
    interpreterOption.setUserPermission(false);
    interpreterOption.owners = owners;
    interpreterSetting = new InterpreterSetting.Builder().setId("id").setName("id").setGroup("group").setOption(interpreterOption).create();
    assertTrue(interpreterSetting.isUserAuthorized(userAndRoles));
}

@Test
void testLoadDependency() throws InterruptedException {
    InterpreterOption interpreterOption = new InterpreterOption();
    interpreterOption.setUserPermission(true);
    InterpreterSetting interpreterSetting = new InterpreterSetting.Builder().setId("id").setName("id").setGroup("group").setOption(interpreterOption).setIntepreterSettingManager(interpreterSettingManager).setDependencyResolver(new DependencyResolver("/tmp", zConf)).setConf(zConf).create();
    // set invalid dependency
    interpreterSetting.setDependencies(Lists.newArrayList(new Dependency("a:b:0.1")));
    long start = System.currentTimeMillis();
    long threshold = 60 * 1000;
    while (interpreterSetting.getStatus() != InterpreterSetting.Status.ERROR && (System.currentTimeMillis() - start) < threshold) {
        Thread.sleep(1000);
        LOGGER.warn("Downloading dependency");
    }
    assertTrue(interpreterSetting.getErrorReason().contains("Cannot fetch dependencies"), interpreterSetting.getErrorReason());
    // clean dependency
    interpreterSetting.setDependencies(new ArrayList<>());
    assertEquals(InterpreterSetting.Status.READY, interpreterSetting.getStatus());
    assertNull(interpreterSetting.getErrorReason());
}

@Test
void testConnectTimeOut() throws IOException {
    SparkInterpreterLauncher launcher = new SparkInterpreterLauncher(zConf, null);
    Properties properties = new Properties();
    properties.setProperty("SPARK_HOME", sparkHome);
    properties.setProperty(ZeppelinConfiguration.ConfVars.ZEPPELIN_INTERPRETER_CONNECT_TIMEOUT.getVarName(), "10000");
    InterpreterOption option = new InterpreterOption();
    option.setUserImpersonate(true);
    InterpreterLaunchContext context = new InterpreterLaunchContext(properties, option, null, "user1", "intpGroupId", "groupId", "groupName", "name", 0, "host");
    InterpreterClient client = launcher.launch(context);
    assertTrue(client instanceof ExecRemoteInterpreterProcess);
    try (ExecRemoteInterpreterProcess interpreterProcess = (ExecRemoteInterpreterProcess) client) {
        assertEquals("name", interpreterProcess.getInterpreterSettingName());
        assertEquals(zeppelinHome + "/interpreter/groupName", interpreterProcess.getInterpreterDir());
        assertEquals(zeppelinHome + "/local-repo/groupId", interpreterProcess.getLocalRepoDir());
        assertEquals(10000, interpreterProcess.getConnectTimeout());
        assertEquals(zConf.getInterpreterRemoteRunnerPath(), interpreterProcess.getInterpreterRunner());
        assertTrue(interpreterProcess.getEnv().size() >= 2);
        assertEquals(true, interpreterProcess.isUserImpersonated());
    }
}

