void testPermissions() throws IOException {
    // create a note and a paragraph
    String noteId = notebook.createNote("note1", anonymous);
    // empty owners, readers or writers means note is public
    assertTrue(authorizationService.isOwner(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertTrue(authorizationService.isReader(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertTrue(authorizationService.isRunner(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertTrue(authorizationService.isWriter(noteId, new HashSet<>(Arrays.asList("user2"))));
    authorizationService.setOwners(noteId, new HashSet<>(Arrays.asList("user1")));
    authorizationService.setReaders(noteId, new HashSet<>(Arrays.asList("user1", "user2")));
    authorizationService.setRunners(noteId, new HashSet<>(Arrays.asList("user3")));
    authorizationService.setWriters(noteId, new HashSet<>(Arrays.asList("user1")));
    assertFalse(authorizationService.isOwner(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertTrue(authorizationService.isOwner(noteId, new HashSet<>(Arrays.asList("user1"))));
    assertFalse(authorizationService.isReader(noteId, new HashSet<>(Arrays.asList("user4"))));
    assertTrue(authorizationService.isReader(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertTrue(authorizationService.isRunner(noteId, new HashSet<>(Arrays.asList("user3"))));
    assertFalse(authorizationService.isRunner(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertFalse(authorizationService.isWriter(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertTrue(authorizationService.isWriter(noteId, new HashSet<>(Arrays.asList("user1"))));
    // Test clearing of permissions
    authorizationService.setReaders(noteId, new HashSet<>());
    assertTrue(authorizationService.isReader(noteId, new HashSet<>(Arrays.asList("user2"))));
    assertTrue(authorizationService.isReader(noteId, new HashSet<>(Arrays.asList("user4"))));
